 const [drawing,setDrawing]=useState(null),[vertices,setVertices]=useState([]),[pan,setPan]=useState({x:0,y:0}),[playPaths,setPlayPaths]=useState(false),[plantArea,setPlantArea]=useState('');
 const [planStep,setPlanStep]=useState(1),[fullLabels,setFullLabels]=useState(false),[savedSnapshot,setSavedSnapshot]=useState('');
 const pendingAction=useRef(null);
 const [storage,setStorage]=useState(null);
 const [library,setLibrary]=useState([]),[dialog,setDialog]=useState(null),[notice,setNotice]=useState(''),[kitNote,setKitNote]=useState(''),[kitPhoto,setKitPhoto]=useState(null),[reportImage,setReportImage]=useState(null);
 const fileRef=useRef(null),kitRef=useRef(null),importRef=useRef(null),markerDrag=useRef(null),noticeTimer=useRef(null);
